  {
   "id": "Q-5",
   "doc": "release_ex99_2.txt",
   "topic": "guidance",
   "text": "For the full year fiscal 2027, we expect GAAP and non-GAAP tax rates to be between 16.0% and 18.0%, excluding any discrete items and material changes to our tax environment."
